import assert from'node:assert/strict';import{Finale,RESULT_DELAY}from'../../public/games/maple-moon-duel/finale.mjs';import{Duel}from'../../public/games/maple-moon-duel/core.mjs';import{AutoDuel}from'../../public/games/maple-moon-duel/auto-duel.mjs';
for(const kind of['cat','xiaosi'])for(const won of[false,true]){const d=new Duel(kind);d.start();const winner=won?d.player:d.enemy,loser=won?d.enemy:d.player;loser.y=200;const f=new Finale(winner,loser,won);assert(!f.step(.3));assert(loser.y>=0&&loser.y<200);assert(!f.step(.5));assert(f.grounded);assert.equal(loser.y,0);const before=f.frame;f.step(.2);assert.notEqual(f.frame,before);assert(!f.step(1.99));assert(f.step(.01));assert.equal(RESULT_DELAY,3);assert.equal(f.winner,winner);assert.equal(f.loser,loser)}
const d=new AutoDuel();d.start();while(!d.ended)d.step(1/60);assert(d.elapsed+RESULT_DELAY+.8<60);console.log('PASS final defeat falls to ground, 16frame breathing, bothrole/win mapping,3s delay, full ending<60s');
